INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind UI/UX-Optimierungen nur für neue Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Bestehende Systeme profitieren ebenso"}, {"text": "Ja", "correct": false, "because": "Verbesserung immer möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit UI/UX-Optimierungen?', 3, '[{"text": "Benutzerfreundlichkeit erhöhen", "correct": true, "because": "Verbessert Nutzererlebnis"}, {"text": "Code effizienter machen", "correct": false, "because": "Nicht primär"}, {"text": "Speicher sparen", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei UI/UX-Optimierungen?', 5, '[{"text": "Usability-Tests", "correct": true, "because": "Zeigt Nutzerprobleme"}, {"text": "Feedback-Schleifen", "correct": true, "because": "Nutzer input einholen"}, {"text": "Performance-Tests", "correct": false, "because": "Technischer Fokus"}, {"text": "Code-Reviews", "correct": false, "because": "Entwicklungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UI/UX verbessert Zufriedenheit. b) Es beschleunigt immer die App.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei UI/UX-Optimierungen?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Kern der Optimierung"}, {"text": "Zielgruppenanalyse", "correct": false, "because": "Definiert Bedürfnisse"}, {"text": "CPU-Auslastung", "correct": true, "because": "Technischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob UI/UX ohne Tests optimiert werden kann?', 2, '[{"text": "Nein", "correct": true, "because": "Tests zeigen Schwächen"}, {"text": "Ja", "correct": false, "because": "Subjektiv ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutze ich für UI/UX-Tests?', 3, '[{"text": "Usability-Tests", "correct": true, "because": "Prüft Nutzererlebnis"}, {"text": "Unit-Tests", "correct": false, "because": "Code-Fokus"}, {"text": "Lasttests", "correct": false, "because": "Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei UI/UX-Optimierungen entscheidend?', 5, '[{"text": "Intuitive Navigation", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Visuelle Klarheit", "correct": true, "because": "Reduziert Verwirrung"}, {"text": "Schnelle Ladezeiten", "correct": false, "because": "Technisch"}, {"text": "Code-Länge", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) UI/UX steigert Nutzerbindung. b) Es ersetzt technische Optimierung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik bleibt nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für UI/UX-Optimierungen?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Zeigt Bedürfnisse"}, {"text": "Prototyping", "correct": false, "because": "Testet Ideen"}, {"text": "Algorithmeneffizienz", "correct": true, "because": "Technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist UI/UX nur für Designer?', 2, '[{"text": "Nein", "correct": true, "because": "Entwickler beeinflussen auch"}, {"text": "Ja", "correct": false, "because": "Teamaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren verbessern UI/UX?', 4, '[{"text": "Konsistentes Design", "correct": true, "because": "Vermindert Verwirrung"}, {"text": "Klare Rückmeldungen", "correct": true, "because": "Nutzer informieren"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass UI/UX nur Ästhetik ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionalität zählt auch"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei UI/UX-Optimierungen?', 3, '[{"text": "Nutzerbedürfnisse", "correct": true, "because": "Zufriedenheit steigern"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Technische Details", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UI/UX reduziert Fehler. b) Es garantiert mehr Nutzer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzung nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet UI/UX-Optimierung?', 5, '[{"text": "Höhere Effizienz", "correct": true, "because": "Nutzer arbeiten schneller"}, {"text": "Bessere Erfahrung", "correct": true, "because": "Zufriedenheit steigt"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht direkt"}, {"text": "Schnellere Server", "correct": false, "because": "Technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei UI/UX-Optimierungen unwichtig?', 3, '[{"text": "Nutzerfreundlichkeit", "correct": false, "because": "Kernziel"}, {"text": "Zugänglichkeit", "correct": false, "because": "Wichtig für Alle"}, {"text": "Speicherbedarf", "correct": true, "because": "Technischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordert UI/UX viel Aufwand?', 3, '[{"text": "Ja", "correct": true, "because": "Tests und Iteration nötig"}, {"text": "Nein", "correct": false, "because": "Aufwand lohnt sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob UI/UX Kundenzufriedenheit steigert?', 2, '[{"text": "Ja", "correct": true, "because": "Besseres Erlebnis"}, {"text": "Nein", "correct": false, "because": "Klarer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei UI/UX-Optimierungen?', 4, '[{"text": "Prototyping-Software", "correct": true, "because": "Testet Designs früh"}, {"text": "Profiler", "correct": false, "because": "Technisch"}, {"text": "Compiler", "correct": false, "because": "Code-Fokus"}]');
